def merge_security_schemes(
    existing: Dict[str, Any], new: Dict[str, Any]
) -> Dict[str, Any]:
    for name, definition in new.items():
        if name in existing:
            existing_def = existing[name]
            if (
                existing_def.get("type") == "oauth2"
                and definition.get("type") == "oauth2"
            ):
                # Merge oauth2 flows
                existing_flows = existing_def.get("flows", {})
                new_flows = definition.get("flows", {})
                for flow_type, flow_def in new_flows.items():
                    if flow_type in existing_flows:
                        existing_scopes = existing_flows[flow_type].get("scopes", {})
                        new_scopes = flow_def.get("scopes", {})
                        existing_scopes.update(new_scopes)
                        existing_flows[flow_type].setdefault("scopes", {}).update(
                            new_scopes
                        )
                    else:
                        existing_flows[flow_type] = flow_def
                existing_def.setdefault("flows", {}).update(existing_flows)
            else:
                existing[name] = definition
        else:
            existing[name] = definition
